def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def digit_sum(n):
        if n < 0:
            # For negative numbers, the first digit is negative
            s = str(n)
            # s starts with '-', so first digit is negative
            # e.g. -123 -> '-123' -> first digit is -1, rest are 2, 3
            # We need to handle this carefully
            # Convert to string, handle the sign
            digits = []
            if s[0] == '-':
                # First digit is negative
                first_digit = -int(s[1])
                digits.append(first_digit)
                for c in s[2:]:
                    digits.append(int(c))
            else:
                for c in s:
                    digits.append(int(c))
            return sum(digits)
        else:
            return sum(int(d) for d in str(n))

    count = 0
    for num in arr:
        if digit_sum(num) > 0:
            count += 1
    return count
