def smartNumber(n):
    """
    Find the n'th smart number.
    A smart number is a number that has exactly 4 distinct prime factors.
    """
    def count_prime_factors(num):
        """Count the number of distinct prime factors of num."""
        if num < 2:
            return 0
        count = 0
        d = 2
        while d * d <= num:
            if num % d == 0:
                count += 1
                while num % d == 0:
                    num //= d
            d += 1
        if num > 1:
            count += 1
        return count

    # Find the n'th smart number
    # Smart numbers have exactly 4 distinct prime factors
    count = 0
    num = 2
    while True:
        if count_prime_factors(num) == 4:
            count += 1
            if count == n:
                return num
        num += 1
